-- Pinuyumayan TTS/STT Music Governance v53
CREATE TABLE IF NOT EXISTS production_evidence_backfill_checks_v53 (check_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), environment VARCHAR(32), status VARCHAR(64), evidence_hash VARCHAR(128), check_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_evidence_dns_records_v53 (dns_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), domain_name VARCHAR(255), cloudflare_proxy_status VARCHAR(32), status VARCHAR(64), evidence_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_evidence_backup_restore_v53 (drill_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), backup_sha256 VARCHAR(128), restore_sha256 VARCHAR(128), row_count_before INT, row_count_after INT, status VARCHAR(64), evidence_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_evidence_observation_windows_v53 (window_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), environment VARCHAR(32), duration_minutes INT, p95_latency_ms INT, error_rate DECIMAL(8,5), status VARCHAR(64), observation_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS production_backfill_seals_v53 (seal_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), evidence_bundle_hash VARCHAR(128), release_allowed BOOLEAN DEFAULT FALSE, status VARCHAR(64), seal_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS legal_speech_evidence_files_v53 (file_id VARCHAR(96) PRIMARY KEY, asset_id VARCHAR(96), actor_id VARCHAR(96), evidence_type VARCHAR(64), file_sha256 VARCHAR(128), scan_status VARCHAR(64), status VARCHAR(64), file_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS legal_speech_asset_approvals_v53 (approval_id VARCHAR(96) PRIMARY KEY, asset_id VARCHAR(96), actor_id VARCHAR(96), license_ok BOOLEAN DEFAULT FALSE, consent_ok BOOLEAN DEFAULT FALSE, alignment_ok BOOLEAN DEFAULT FALSE, native_review_ok BOOLEAN DEFAULT FALSE, eligible_for_export BOOLEAN DEFAULT FALSE, status VARCHAR(64), approval_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS legal_speech_exports_v53 (export_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), train_rows INT DEFAULT 0, dev_rows INT DEFAULT 0, test_rows INT DEFAULT 0, export_allowed BOOLEAN DEFAULT FALSE, status VARCHAR(64), export_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS music_search_ranking_metrics_v53 (metric_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), feature VARCHAR(64), variant VARCHAR(64), uplift_pct DECIMAL(8,4), status VARCHAR(64), metric_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS music_search_ranking_rollouts_v53 (rollout_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), feature VARCHAR(64), rollout_percent INT, status VARCHAR(64), rollout_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS music_search_synonym_merge_tasks_v53 (task_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), term VARCHAR(255), status VARCHAR(64), task_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authority_metadata_public_cards_v53 (publication_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), route_path VARCHAR(255), rights_approved BOOLEAN DEFAULT FALSE, index_status VARCHAR(64), status VARCHAR(64), metadata_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authority_metadata_source_changes_v53 (change_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), source_id VARCHAR(96), change_type VARCHAR(64), status VARCHAR(64), change_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authority_metadata_takedown_tests_v53 (test_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), publication_id VARCHAR(96), status VARCHAR(64), test_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS speech_model_governance_pdfs_v53 (pdf_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), artifact_path VARCHAR(255), watermark VARCHAR(255), status VARCHAR(64), pdf_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS speech_model_signoff_sections_v53 (section_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), status VARCHAR(64), section_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS speech_model_release_blockers_v53 (blocker_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), status VARCHAR(64), blocker_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_uptime_samples_v53 (sample_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), route_path VARCHAR(255), status_code INT, latency_ms INT, status VARCHAR(64), sample_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_error_rate_samples_v53 (sample_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), route_path VARCHAR(255), error_rate DECIMAL(8,5), status VARCHAR(64), sample_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_ops_reports_v53 (report_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), cadence VARCHAR(32), report_status VARCHAR(64), status VARCHAR(64), report_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_alert_notifications_v53 (alert_id VARCHAR(96) PRIMARY KEY, actor_id VARCHAR(96), alert_type VARCHAR(64), status VARCHAR(64), alert_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
